class Solution:
    def minBitwiseArray(self, nums: List[int]) -> List[int]:
        # ans | (ans + 1) == num
        # If ans ends with t trailing ones, then ans + 1 clears them and sets bit t,
        # so ans | (ans + 1) == ans | (1 << t) == num, where num has bits 0..t all set.
        # Hence ans = num - (1 << t), valid for any t <= (trailing ones of num) - 1.
        # To minimize ans we take the largest such t.
        res = []
        for num in nums:
            if num % 2 == 0:
                # ans | (ans + 1) is always odd, so an even target is impossible.
                res.append(-1)
                continue
            k = 0
            v = num
            while v & 1:
                k += 1
                v >>= 1
            res.append(num - (1 << (k - 1)))
        return res


