class Solution:
    def countPathsWithXorValue(self, grid: List[List[int]], k: int) -> int:
        MOD = 10**9 + 7
        m = len(grid)
        n = len(grid[0])

        # dp[j] = list of 16 counters: number of paths reaching cell (i, j)
        # whose XOR (including the cell itself) equals the index.
        dp = [None] * n

        for i in range(m):
            row = grid[i]
            for j in range(n):
                v = row[j]
                if i == 0 and j == 0:
                    nd = [0] * 16
                    nd[v] = 1
                else:
                    if i == 0:
                        base = dp[j - 1]          # only from the left
                    elif j == 0:
                        base = dp[j]              # only from above (row i-1)
                    else:
                        up = dp[j]                # still holds row i-1
                        left = dp[j - 1]          # already updated to row i
                        base = [(a + b) % MOD for a, b in zip(up, left)]

                    nd = [0] * 16
                    for t in range(16):
                        c = base[t]
                        if c:
                            nd[t ^ v] = c
                dp[j] = nd

        return dp[n - 1][k] % MOD

