class Solution:
    def checkValidCuts(self, n: int, rectangles: List[List[int]]) -> bool:
        def count_groups(intervals):
            # intervals: list of (start, end) with start < end
            intervals.sort()
            groups = 0
            cur_end = -1
            for s, e in intervals:
                if s >= cur_end:
                    # a cut can be placed at s (or before), closing previous group
                    groups += 1
                    cur_end = e
                else:
                    if e > cur_end:
                        cur_end = e
                if groups >= 3:
                    return groups
            return groups

        xs = [(r[0], r[2]) for r in rectangles]
        if count_groups(xs) >= 3:
            return True
        ys = [(r[1], r[3]) for r in rectangles]
        return count_groups(ys) >= 3

