class Solution:
    def minOperations(self, nums: List[int]) -> int:
        # Dividing x by its greatest proper divisor leaves exactly spf(x),
        # the smallest prime factor of x (for x > 1). Applying the operation
        # again on a prime leaves it unchanged, so every element has at most
        # two useful states: nums[i] or spf(nums[i]).
        n = len(nums)
        if n <= 1:
            return 0

        mx = max(nums)
        spf = list(range(mx + 1))
        i = 2
        while i * i <= mx:
            if spf[i] == i:  # i is prime
                for j in range(i * i, mx + 1, i):
                    if spf[j] == j:
                        spf[j] = i
            i += 1

        # Sweep right to left keeping the largest feasible value (which also
        # costs the fewest operations, so the greedy choice dominates).
        ops = 0
        prev = nums[-1]
        for k in range(n - 2, -1, -1):
            v = nums[k]
            if v <= prev:
                prev = v
            else:
                s = spf[v]
                if s <= prev:
                    ops += 1
                    prev = s
                else:
                    return -1
        return ops

