class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        INF = float('inf')
        # best[r] = minimum prefix sum seen at an index i with i % k == r
        best = [INF] * k

        ans = -INF
        pref = 0
        for j in range(n + 1):
            if j > 0:
                pref += nums[j - 1]
            r = j % k
            if best[r] is not INF and best[r] != INF:
                cand = pref - best[r]
                if cand > ans:
                    ans = cand
            if pref < best[r]:
                best[r] = pref

