class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)

        # steps[m] = minimum number of popcount-operations to reduce m to 1
        steps = [0] * (L + 2)
        for m in range(2, L + 1):
            steps[m] = 1 + steps[bin(m).count('1')]

        # A number x > 1 with popcount c is k-reducible iff steps[c] <= k - 1.
        # x = 1 has popcount 1 and steps[1] = 0 <= k - 1 (k >= 1), so it is included too.
        valid = [c for c in range(1, L + 1) if steps[c] <= k - 1]

        # Pascal's triangle up to L
        C = [[0] * (L + 1) for _ in range(L + 1)]
        for i in range(L + 1):
            C[i][0] = 1
            for j in range(1, i + 1):
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

        ans = 0
        ones = 0
        for i in range(L):
            if s[i] == '1':
                rem = L - i - 1
                for c in valid:
                    need = c - ones
                    if 0 <= need <= rem:
                        ans += C[rem][need]
                ans %= MOD
                ones += 1

        return ans % MOD

