class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        # Answer = (# of k outside the chosen subarray) + max over v of (# of v inside)
        #        = total_k + max(0, max over v != k of Kadane(+1 for v, -1 for k))
        # Kadane for all 50 values at once: only the bucket of the current element
        # increases; a k decrements every bucket (handled lazily via the counter K,
        # since repeated max(cur-1,0) equals max(cur-m,0)).
        raw = [0] * 51          # raw[v] = cur_v + K at last update
        best = [0] * 51
        K = 0                   # number of k's seen so far
        total_k = 0
        for a in nums:
            if a == k:
                K += 1
                total_k += 1
            else:
                c = raw[a] - K
                if c < 0:
                    c = 0
                c += 1
                raw[a] = c + K
                if c > best[a]:
                    best[a] = c
        return total_k + max(best)

