def main():
    data = sys.stdin.buffer.read().split()
    N = int(data[0]); M = int(data[1]); K = int(data[2])
    X = [int(v) for v in data[3:3 + M]]
    MOD = 998244353
    m = K - 1

    LIM = max(N, K) + 10
    fact = [1] * (LIM + 1)
    for i in range(1, LIM + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (LIM + 1)
    inv_fact[LIM] = pow(fact[LIM], MOD - 2, MOD)
    for i in range(LIM, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def comb(a, b):
        if b < 0 or a < 0 or b > a:
            return 0
        return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

    # f[n] = number of length-n sequences over a fixed (K-1)-letter alphabet
    # that use every one of those letters at least once (surjections).
    f = [0] * (N + 1)
    for i in range(m + 1):
        base = (m - i) % MOD
        c = comb(m, i)
        if i & 1:
            c = (MOD - c) % MOD
        if c == 0:
            continue
        f[0] = (f[0] + c) % MOD  # base^0 = 1
        cur = 1
        if base == 0:
            continue
        for n in range(1, N + 1):
            cur = cur * base % MOD
            f[n] = (f[n] + c * cur) % MOD

    def pmul(a, b):
        res = [0] * (N + 1)
        for i in range(N + 1):
            ai = a[i]
            if ai:
                top = N - i
                for j in range(top + 1):
                    bj = b[j]
                    if bj:
                        res[i + j] = (res[i + j] + ai * bj) % MOD
        return res

    # result = F(x)^M truncated at degree N
    result = [0] * (N + 1)
    result[0] = 1
    baseP = f[:]
    e = M
    while e:
        if e & 1:
            result = pmul(result, baseP)
        e >>= 1
        if e:
            baseP = pmul(baseP, baseP)

    S = 0
    for j in range(M - 1):
        if X[j] == X[j + 1]:
            S += 1
    E = (M - 1) - S
    rem = N - S

    ans = 0
    if rem >= 0:
        if E == 0:
            if 0 <= rem <= N:
                ans = result[rem]
        else:
            c = (K - 2) % MOD
            n = 2 * E
            cp = 1
            while n <= rem:
                t = rem - n
                coef = comb(n - E - 1, E - 1) * cp % MOD
                if coef:
                    ans = (ans + coef * result[t]) % MOD
                n += 1
                cp = cp * c % MOD

    sys.stdout.write(str(ans % MOD) + "\n")


