from bisect import bisect_left, bisect_right


def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    m = int(data[1])
    Rs = set()
    Cs = set()
    Ps = set()
    Qs = set()
    pos = 2
    for _ in range(m):
        a = int(data[pos])
        b = int(data[pos + 1])
        pos += 2
        Rs.add(a)
        Cs.add(b)
        Ps.add(a + b)
        Qs.add(a - b)

    R = sorted(Rs)
    C = sorted(Cs)
    P = sorted(Ps)
    Q = sorted(Qs)

    freeRows = n - len(R)

    # T0: rows free x columns not blocked by the column-set
    total = (n - len(C)) * freeRows

    # T2 = sum over free rows i of #{p in P : 1 <= p-i <= n}
    T2 = 0
    for p in P:
        lo = p - n
        if lo < 1:
            lo = 1
        hi = p - 1
        if hi > n:
            hi = n
        if hi >= lo:
            T2 += (hi - lo + 1) - (bisect_right(R, hi) - bisect_left(R, lo))

    # T3 = sum over free rows i of #{q in Q : 1 <= i-q <= n}
    T3 = 0
    for q in Q:
        lo = q + 1
        if lo < 1:
            lo = 1
        hi = q + n
        if hi > n:
            hi = n
        if hi >= lo:
            T3 += (hi - lo + 1) - (bisect_right(R, hi) - bisect_left(R, lo))

    total -= T2 + T3

    # T12 = #{(p,c) : i = p-c in [1,n] and i not in R}
    T12 = 0
    for c in C:
        lo = c + 1
        hi = c + n
        T12 += bisect_right(P, hi) - bisect_left(P, lo)
        if R:
            T12 -= len(Ps & {c + r for r in R})

    # T13 = #{(q,c) : i = q+c in [1,n] and i not in R}
    T13 = 0
    for c in C:
        lo = 1 - c
        hi = n - c
        T13 += bisect_right(Q, hi) - bisect_left(Q, lo)
        if R:
            T13 -= len(Qs & {r - c for r in R})

    total += T12 + T13

    # T23 = #{(p,q) : p+q even, i=(p+q)/2 in [1,n]\R, 1 <= (p-q)/2 <= n}
    Qe = [q for q in Q if q % 2 == 0]
    Qo = [q for q in Q if q % 2 != 0]
    n2 = 2 * n
    T23 = 0
    for p in P:
        L = Qe if p % 2 == 0 else Qo
        lo = 2 - p
        t = p - n2
        if t > lo:
            lo = t
        hi = n2 - p
        t = p - 2
        if t < hi:
            hi = t
        if hi >= lo and L:
            T23 += bisect_right(L, hi) - bisect_left(L, lo)
        if R:
            T23 -= len(Qs & {2 * r - p for r in R if 1 <= p - r <= n})

    total += T23

    # T123 = #{(i,c) : c in C, i in [1,n]\R, i+c in P, i-c in Q}
    T123 = 0
    for c in C:
        s1 = {p - c for p in P}
        if not s1:
            continue
        s2 = {q + c for q in Q}
        for i in (s1 & s2):
            if 1 <= i <= n and i not in Rs:
                T123 += 1

    total -= T123

    sys.stdout.write(str(total) + "\n")


