class Solution:
    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        n = len(nums)
        op1 = min(op1, n)
        op2 = min(op2, n)
        INF = float('inf')

        # dp[a][b] = min sum so far using exactly a ops of type 1 and b of type 2
        dp = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
        dp[0][0] = 0

        for v in nums:
            # candidate values
            base = v
            only1 = (v + 1) // 2
            only2 = v - k if v >= k else None

            both = None
            # order: op1 then op2
            t = only1
            if t >= k:
                both = t - k
            # order: op2 then op1
            if v >= k:
                t2 = (v - k + 1) // 2
                if both is None or t2 < both:
                    both = t2

            ndp = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
            for a in range(op1 + 1):
                row = dp[a]
                for b in range(op2 + 1):
                    cur = row[b]
                    if cur == INF:
                        continue
                    # no operation
                    if cur + base < ndp[a][b]:
                        ndp[a][b] = cur + base
                    # operation 1 only
                    if a < op1:
                        if cur + only1 < ndp[a + 1][b]:
                            ndp[a + 1][b] = cur + only1
                    # operation 2 only
                    if b < op2 and only2 is not None:
                        if cur + only2 < ndp[a][b + 1]:
                            ndp[a][b + 1] = cur + only2
                    # both operations
                    if a < op1 and b < op2 and both is not None:
                        if cur + both < ndp[a + 1][b + 1]:
                            ndp[a + 1][b + 1] = cur + both
            dp = ndp

        best = INF
        for a in range(op1 + 1):
            for b in range(op2 + 1):
                if dp[a][b] < best:
                    best = dp[a][b]
        return int(best)

