class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        # Precompute maximal runs of identical characters.
        runs = []
        i = 0
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            runs.append(j - i)
            i = j

        # Cost for k == 1: the string must be strictly alternating.
        diff = 0
        for idx, ch in enumerate(s):
            if ch != ('0' if idx % 2 == 0 else '1'):
                diff += 1
        cost_one = min(diff, n - diff)

        def cost(k: int) -> int:
            if k == 1:
                return cost_one
            # For k >= 2, each run of length L needs L // (k + 1) flips,
            # and the flipped positions can always be chosen strictly
            # inside the run, so runs never merge.
            total = 0
            for L in runs:
                total += L // (k + 1)
            return total

        for k in range(1, n + 1):
            if cost(k) <= numOps:
                return k
        return n

