from collections import defaultdict, deque


def main():
    sys.setrecursionlimit(5000)
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    names = data[1:1 + n]
    n = len(names)
    if n == 0:
        print(0)
        return

    by_first = defaultdict(list)
    for i, s in enumerate(names):
        by_first[s[0]].append(i)

    # Graph on product names: "ab" -> "bc"
    adj = []
    for i, s in enumerate(names):
        adj.append(by_first.get(s[1], []))

    # ---- Kosaraju SCC ----
    visited = [False] * n
    order = []
    for start in range(n):
        if visited[start]:
            continue
        visited[start] = True
        stack = [(start, 0)]
        while stack:
            v, pi = stack[-1]
            av = adj[v]
            if pi < len(av):
                stack[-1] = (v, pi + 1)
                w = av[pi]
                if not visited[w]:
                    visited[w] = True
                    stack.append((w, 0))
            else:
                order.append(v)
                stack.pop()

    radj = [[] for _ in range(n)]
    for v in range(n):
        for w in adj[v]:
            radj[w].append(v)

    comp = [-1] * n
    c = 0
    for v in reversed(order):
        if comp[v] != -1:
            continue
        comp[v] = c
        stack = [v]
        while stack:
            x = stack.pop()
            for y in radj[x]:
                if comp[y] == -1:
                    comp[y] = c
                    stack.append(y)
        c += 1
    C = c

    succ = [set() for _ in range(C)]
    for v in range(n):
        cv = comp[v]
        for w in adj[v]:
            cw = comp[w]
            if cv != cw:
                succ[cv].add(cw)

    indeg = [0] * C
    for u in range(C):
        for v in succ[u]:
            indeg[v] += 1

    dq = deque(u for u in range(C) if indeg[u] == 0)
    topo = []
    while dq:
        u = dq.popleft()
        topo.append(u)
        for v in succ[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                dq.append(v)

    # Transitive closure over the condensation DAG (bitsets)
    reach = [0] * C
    for u in reversed(topo):
        r = 0
        for v in succ[u]:
            r |= (1 << v) | reach[v]
        reach[u] = r

    # Minimum path cover on the closure = C - maximum bipartite matching
    matchR = [-1] * C
    vis = 0

    def dfs(u):
        nonlocal vis
        avail = reach[u] & ~vis
        while avail:
            low = avail & -avail
            v = low.bit_length() - 1
            vis |= low
            mv = matchR[v]
            if mv == -1 or dfs(mv):
                matchR[v] = u
                return True
            avail = reach[u] & ~vis
        return False

    res = 0
    for u in range(C):
        if reach[u]:
            vis = 0
            if dfs(u):
                res += 1

    print(C - res)


