class Solution:
    def minOperations(self, n: int, m: int) -> int:
        d = len(str(n))
        LIMIT = 10 ** d

        # Sieve of Eratosthenes over all values reachable with d digit positions
        is_prime = [True] * LIMIT
        is_prime[0] = False
        if LIMIT > 1:
            is_prime[1] = False
        i = 2
        while i * i < LIMIT:
            if is_prime[i]:
                for j in range(i * i, LIMIT, i):
                    is_prime[j] = False
            i += 1

        if is_prime[n] or is_prime[m]:
            return -1

        INF = float('inf')
        dist = [INF] * LIMIT
        dist[n] = n
        pq = [(n, n)]

        while pq:
            cost, cur = heapq.heappop(pq)
            if cost > dist[cur]:
                continue
            if cur == m:
                return cost
            s = str(cur).zfill(d)
            for pos in range(d):
                c = ord(s[pos]) - 48
                for nc in (c - 1, c + 1):
                    if 0 <= nc <= 9:
                        nxt = int(s[:pos] + chr(48 + nc) + s[pos + 1:])
                        if is_prime[nxt]:
                            continue
                        nd = cost + nxt
                        if nd < dist[nxt]:
                            dist[nxt] = nd
                            heapq.heappush(pq, (nd, nxt))

        return -1

