import sys


def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    X = int(data[1])
    procs = []
    idx = 2
    for _ in range(n):
        A = int(data[idx]); P = int(data[idx + 1])
        B = int(data[idx + 2]); Q = int(data[idx + 3])
        idx += 4
        procs.append((A, P, B, Q))

    # Upper bound on the achievable capacity: even spending the whole budget on
    # the cheapest machine of the most productive process gives at most this.
    hi = min(max(A, B) * (X // min(P, Q)) for A, P, B, Q in procs)

    def feasible(W):
        # Minimum total cost to make every process handle >= W products/day.
        total = 0
        for A, P, B, Q in procs:
            best = None
            # An optimal (a, b) has a <= B or b <= A: B units of S and A units
            # of T give the same throughput (A*B), so excess can be swapped.
            for a in range(0, B + 1):
                rem = W - a * A
                if rem <= 0:
                    c = a * P
                else:
                    c = a * P + ((rem + B - 1) // B) * Q
                if best is None or c < best:
                    best = c
                if rem <= 0:
                    break
            for b in range(0, A + 1):
                rem = W - b * B
                if rem <= 0:
                    c = b * Q
                else:
                    c = b * Q + ((rem + A - 1) // A) * P
                if c < best:
                    best = c
                if rem <= 0:
                    break
            total += best
            if total > X:
                return False
        return total <= X

    lo = 0
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1
    sys.stdout.write(str(lo) + "\n")


main()
